"use client";

import { useState } from "react";
import {
  type FrequencyShifterState,
  frequencyShifterDevice,
} from "@/components/audio-ui/devices/frequency-shifter/device";
import { createFrequencyShifterEngine } from "@/components/audio-ui/devices/frequency-shifter/engine";
import { FrequencyShifterPanel } from "@/components/audio-ui/devices/frequency-shifter/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useMasterBus } from "@/hooks/use-master-bus";

const MASTER_VOLUME = 0.7;

/**
 * A frequency shifter you can plug in: its state, a panel that draws what it
 * does to a note and its harmonics and an engine that plays it, each its own
 * file and none knowing the others. Play the loop and turn the shift.
 */
export function BlockFrequencyShifter() {
  const [state, setState] = useState<FrequencyShifterState>(() =>
    frequencyShifterDevice.defaults()
  );
  const master = useMasterBus(MASTER_VOLUME);
  useDeviceLoop({
    create: createFrequencyShifterEngine,
    destination: master,
    state,
  });
  return (
    <div className="rounded-2xl h-full w-full min-w-0">
      <FrequencyShifterPanel onValueChange={setState} value={state} />
    </div>
  );
}
